import type { System } from "../../Engine/System";
import type { World } from "../../Engine/World";
import type { Plane } from "../Entity/Plane";
import { BATTLE_EVENT } from "../BattleEvents";

export class FireSystem implements System {
    
    onTick(world:World,dt:number): void{
        for (const p of world.query<Plane>('player')) {
            this._tickWeapons(world, p, dt);
        }
        for (const p of world.query<Plane>('enemy')) {
            this._tickWeapons(world, p, dt);
        }
    }

    private _tickWeapons(world: World, p: Plane, dt: number): void {
        for (const w of p.weapons) {
            if (!w.enabled) continue;

            w.cooldownTimer += dt;

            // while + guard：一帧内可能多次开火（高射速武器）
            let guard = 0;
            while (w.cooldownTimer >= w.config.fireInterval && guard++ < 16) {
                w.cooldownTimer -= w.config.fireInterval;
                world.bus.emit(BATTLE_EVENT.WEAPON_FIRE, p, w);
            }
        }
    }
    
}


